const body = $input.item.json.body || $input.item.json;
const headers = $input.item.json.headers || {};
const secretToken = process.env.TELEGRAM_SECRET_TOKEN || (typeof $env !== 'undefined' ? $env.TELEGRAM_SECRET_TOKEN : '');
const incomingToken = headers['x-telegram-bot-api-secret-token'];

// 1. Verify Secret Token if configured
if (secretToken && incomingToken && secretToken !== incomingToken) {
  return [{ json: { isValid: false, reason: 'Invalid secret token header' } }];
}

const message = body.message || body.edited_message;
if (!message || typeof message !== 'object') {
  return [{ json: { isValid: false, reason: 'No message object in payload' } }];
}

// 2. Limit accepted message types: text only
if (!message.text || message.text.trim() === '') {
  return [{ json: { isValid: false, reason: 'Non-text message ignored (accepted: text only)' } }];
}

const fromUser = message.from || {};
const chat = message.chat || {};
const firstName = fromUser.first_name || chat.first_name || '';
const lastName = fromUser.last_name || chat.last_name || '';
const fullName = [firstName, lastName].filter(Boolean).join(' ') || fromUser.username || 'Telegram User';

return [{
  json: {
    isValid: true,
    telegram_message_id: message.message_id.toString(),
    chat_id: chat.id.toString(),
    telegram_username: fromUser.username ? '@' + fromUser.username : '',
    customer_name: fullName,
    message_text: message.text.trim(),
    message_type: 'text',
    timestamp: message.date
  }
}];

