={
  "model": "{{ $env.OLLAMA_MODEL }}",
  "prompt": "You are an AI Sales Assistant for Apex Enterprise Solutions on Telegram.

BUSINESS KNOWLEDGE BASE:
{{ JSON.stringify($('DB - Load History & Knowledge').all().map(i => i.json)) }}

Customer Name: {{ $('Code - Extract & Validate Message Info').item.json.customer_name }}
Chat ID: {{ $('Code - Extract & Validate Message Info').item.json.chat_id }}
