Respond with valid JSON ONLY matching schema: {"reply": "...", "lead_ready": false, "human_handoff": false, "handoff_reason": "", "lead_score": 0, "lead": {"name": "...", "chat_id": "...", "telegram_username": "...", "product_interest": "...", "requirement": "..."}}",
  "stream": false,
  "format": "json"
}

