try {
  const responseText = $input.item.json.response;
  const parsed = JSON.parse(responseText);
  return [{ json: { success: true, ai_output: parsed } }];
} catch (e) {
  return [{
    json: {
      success: false,
      ai_output: {
        reply: 'Thank you for your message. We are experiencing a temporary technical issue. A team member will assist you shortly.',
        lead_ready: true,
        human_handoff: true,
        handoff_reason: 'AI JSON Parse Error',
        lead_score: 50,
        lead: {}
      }
    }
  }];
}

return [{
  json: {
    success: true,
    ai_output: {
      reply: 'Thank you for your message. Our automated AI assistant is currently paused. A team representative will reply to you shortly.',
      lead_ready: true,
      human_handoff: true,
      handoff_reason: 'AI Assistant Disabled Manually',
      lead_score: 0,
      lead: {}
    }
  }
}];

const odooUrl = ($env.ODOO_URL || 'http://host.docker.internal:8069').replace(/\/$/, '');
const odooDb = $env.ODOO_DB || 'odoo_db';
const odooUser = $env.ODOO_USERNAME || 'admin@example.com';
const odooPass = $env.ODOO_PASSWORD || 'admin_password';

const extracted = $('Code - Extract & Validate Message Info').item.json;
const parseNode = $('Code - Parse AI Response').item.json || {};
const aiOutput = parseNode.ai_output || {};
const leadData = aiOutput.lead || {};

const chatId = extracted.chat_id || '';
const telegramUsername = extracted.telegram_username || '';
const customerName = leadData.name || extracted.customer_name || 'Telegram User';
const productInterest = leadData.product_interest || '';
const requirement = leadData.requirement || extracted.message_text || '';
const leadScore = aiOutput.lead_score || 0;
const aiReply = aiOutput.reply || '';
const handoffReason = aiOutput.handoff_reason || '';

try {
  const authRes = await fetch(`${odooUrl}/jsonrpc`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'common',
        method: 'authenticate',
        args: [odooDb, odooUser, odooPass, {}]
      },
      id: 1
    })
  });
  const authJson = await authRes.json();
  const uid = authJson.result;

  if (!uid) {
    return [{ json: { status: 'Odoo Auth Failed', error: authJson.error || 'Invalid credentials or DB' } }];
  }

  const searchRes = await fetch(`${odooUrl}/jsonrpc`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          odooDb, uid, odooPass,
          'crm.lead', 'search',
          [[['x_telegram_chat_id', '=', chatId]]]
        ]
      },
      id: 2
    })
  });
  const searchJson = await searchRes.json();
  const leadIds = searchJson.result || [];

  const leadFields = {
    name: `Telegram Lead - ${customerName} (${chatId})`,
    contact_name: customerName,
    x_telegram_chat_id: chatId,
    x_telegram_username: telegramUsername,
    x_product_interest: productInterest,
    x_customer_requirement: requirement,
    x_ai_lead_score: leadScore,
    x_ai_summary: aiReply,
    x_handoff_reason: handoffReason
  };

  if (leadIds.length > 0) {
    const leadId = leadIds[0];
    await fetch(`${odooUrl}/jsonrpc`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        jsonrpc: '2.0',
        method: 'call',
        params: {
          service: 'object',
          method: 'execute_kw',
          args: [
            odooDb, uid, odooPass,
            'crm.lead', 'write',
            [[leadId], leadFields]
          ]
        },
        id: 3
      })
    });
    return [{ json: { status: 'Lead Updated in Odoo', lead_id: leadId, chat_id: chatId } }];
  } else {
    const createRes = await fetch(`${odooUrl}/jsonrpc`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        jsonrpc: '2.0',
        method: 'call',
        params: {
          service: 'object',
          method: 'execute_kw',
          args: [
            odooDb, uid, odooPass,
            'crm.lead', 'create',
            [leadFields]
          ]
        },
        id: 4
      })
    });
    const createJson = await createRes.json();
    const newLeadId = createJson.result;
    return [{ json: { status: 'Lead Created in Odoo', lead_id: newLeadId, chat_id: chatId } }];
  }
} catch (err) {
  return [{ json: { status: 'Odoo Lead Sync Error', error: err.message } }];
}
